import{_ as t,o as i,c as r,ah as n}from"./chunks/framework.DDXs_i7t.js";const p=JSON.parse('{"title":"Research: The \\"Ticker Ban\\" in the Wöginger Trial","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/2026-03-26-tickerverbot-woeginger.md","filePath":"en/recherche/2026-03-26-tickerverbot-woeginger.md"}'),o={name:"en/recherche/2026-03-26-tickerverbot-woeginger.md"};function a(s,e,h,c,l,g){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="research-the-ticker-ban-in-the-woginger-trial" tabindex="-1">Research: The &quot;Ticker Ban&quot; in the Wöginger Trial <a class="header-anchor" href="#research-the-ticker-ban-in-the-woginger-trial" aria-label="Permalink to &quot;Research: The &quot;Ticker Ban&quot; in the Wöginger Trial&quot;">​</a></h1><p><strong>Date:</strong> March 26, 2026 <strong>Source:</strong> Ö1 Mittagsjournal / Media Reports</p><h3 id="summary-of-events" tabindex="-1">Summary of Events <a class="header-anchor" href="#summary-of-events" aria-label="Permalink to &quot;Summary of Events&quot;">​</a></h3><p>On March 24, 2026, the Linz Regional Court issued a surprising ban on live tickers from the courtroom during the trial against ÖVP club chairman August Wöginger.</p><p><strong>The Court&#39;s Reasoning:</strong> The presiding judge argued that the immediate publication of witness testimony in real-time posed a risk that subsequent witnesses could adapt their statements. To avoid jeopardizing the pursuit of truth, live reporting was prohibited.</p><p><strong>The Criticism:</strong> The decision sparked a heated debate about press freedom and the principle of public access to court proceedings.</p><ul><li><strong>Legal Experts:</strong> Criticized that witnesses could inform themselves anyway via radio, television, or evening newspapers. A ticker ban was an &quot;anachronistic intervention&quot; in the digital age.</li><li><strong>Journalist Organizations:</strong> Saw it as a dangerous restriction on reporting on a trial of high public interest.</li></ul><p><strong>Substantive Context of the Trial:</strong> In parallel with the debate over the ticker ban, the core allegations were recapitulated in the Mittagsjournal:</p><ul><li>Wöginger&#39;s intervention with Thomas Schmid (then Ministry of Finance) in 2017.</li><li>Goal: Appointment of an ÖVP mayor as head of the Braunau tax office, despite lower qualifications (62 vs. 98 points).</li><li>New witness testimony confirmed the pressure on the top-ranked candidate to waive the post.</li></ul><h3 id="context-for-the-docfilm" tabindex="-1">Context for the Docfilm <a class="header-anchor" href="#context-for-the-docfilm" aria-label="Permalink to &quot;Context for the Docfilm&quot;">​</a></h3><p>The ticker ban is another piece of the puzzle in the narrative of the <strong>&quot;System of Intransparency&quot;</strong>. While we follow the &quot;pointillism of money&quot; (the visible traces) in the film, the ticker ban shows the attempt to prevent the visibility of the legal process in real-time.</p><p><strong>Status Update (03/27/2026):</strong> The ban was lifted on the morning of March 27, 2026, by Judge Melanie Halbig.</p><ul><li><strong>Reasoning:</strong> The witnesses called today predominantly have &quot;indirect perceptions&quot; (e.g., tax office internal &quot;corridor radio&quot;), which means that mutual influence by ticker content is no longer given.</li><li><strong>Conclusion for Research:</strong> The ticker intermezzo has shown how fragile transparency can be in trials against top politicians. The media and legal resistance to the ban was decisive for the rapid correction. The verdict against August Wöginger is now expected for <strong>May 4, 2026</strong>.</li></ul><p><em>Documented for the project &quot;HortenMystery&quot;.</em></p>',14)])])}const d=t(o,[["render",a]]);export{p as __pageData,d as default};
